// Precheck: 计算文件 SHA-256，检查重复
const crypto = require('crypto');
const body = $input.first().json;

const content = body.content || '';
const fileName = body.file_name || 'untitled';
const fileHash = crypto.createHash('sha256').update(content).digest('hex');

return {
  json: {
    ...body,
    file_name: fileName,
    file_hash: fileHash,
    task_status: 'PRECHECKING',
    received_at: new Date().toISOString()
  }
};

// Routing: 规则优先，LLM 只给候选
// Phase 1 简化版：按文件名/用户指令做规则路由
const input = $input.first().json;
const fileName = input.file_name.toLowerCase();
const instruction = (input.user_instruction || '').toLowerCase();

let category = '01_Work';  // 默认
let spaceId = 'space_personal_u1';

// 规则 R-01: 健康关键词 → 04_Health_Archive
if (/体检|血压|血糖|医院|医生|处方|化验|健康/.test(fileName + instruction)) {
  category = '04_Health_Archive';
}
// 规则 R-02: 家庭关键词 → 03_Family
else if (/家庭|孩子|女儿|父母|生日|派对/.test(fileName + instruction)) {
  category = '03_Family';
}
// 规则 R-03: 生活关键词 → 02_Life
else if (/生活|购物|旅游|美食|电影/.test(fileName + instruction)) {
  category = '02_Life';
}

return {
  json: {
    ...input,
    routed_category: category,
    routed_space: spaceId,
    routing_rule: 'R-0x',
    task_status: 'ROUTING'
  }
};

// 生成引用锚点，写 Living Ledger
const input = $input.first().json;
const docId = input.doc_id;

const ledgerEntry = `## ${new Date().toISOString()} 入库\n- doc: 《${input.file_name}》\n- doc_id: ${docId}\n- 路由: ${input.routed_category} → 规则 ${input.routing_rule}\n- SHA-256: ${input.file_hash.substring(0, 16)}...\n`;

return {
  json: {
    ...input,
    doc_id: docId,
    ledger_entry: ledgerEntry,
    task_status: 'COMMITTED'
  }
};
